#ifndef WS_LOG_LEVEL_H
#define WS_LOG_LEVEL_H

#include <string>
#include <iostream>

namespace ws::log {

enum class Level {
    Debug,
    Info,
    Warn,
    Error,
    Fatal
};

std::string LevelToString(Level level);
std::string to_string(Level level) { return LevelToString(level); }
Level StringToLevel(const std::string& str);

}
#endif // WS_LOG_LEVEL_H

#ifndef WS_LOG_APPENDER_TYPE_H
#define WS_LOG_APPENDER_TYPE_H

#include <string>
#include <iostream>

namespace ws::log {

enum class AppenderType {
    StdOut,
    File
};

std::string AppenderTypeToString(AppenderType type);
std::string to_string(AppenderType type) { return AppenderTypeToString(type); }
AppenderType StringToAppenderType(const std::string& str);

}
#endif // WS_LOG_APPENDER_TYPE_H

#ifndef WS_LOG_EVENT_H
#define WS_LOG_EVENT_H

#include <memory>
#include <string>
#include <sstream>
#include <chrono>
#include <thread>

namespace ws::log {

enum class Level;

enum class AppenderType;

class Event {
public:
    static std::shared_ptr<Event> Create(Level level, const std::string& file, int line, const std::string& message);

    Level Level() const; 
    const std::string& FileName() const; 
    int LineNumber() const; 
    const std::string& Message() const;
    std::chrono::system_clock::time_point Timestamp() const;
    std::thread::id ThreadId() const;

private:
    Event(Level level, const std::string& file, int line, const std::string& message);

    Level level_;
    std::string file_; 
    int line_; 
    std::string message_; 
    std::chrono::system_clock::time_point timestamp_; 
    std::thread::id thread_id_;

    std::ostringstream message_stream_; // For incremental message building.
public:
    std::ostringstream& MessageStream();
};

using EventPtr = std::shared_ptr<Event>;
}
#endif // WS_LOG_EVENT_H

#ifndef WS_LOG_FORMATTER_H
#define WS_LOG_FORMATTER_H

#include <memory>
#include <string>
#include <sstream>
#include <vector>

namespace ws::log {

class Event;

class Formatter {
public:
    virtual ~Formatter() = default;
    virtual std::string Format(const EventPtr& event) const = 0;

    static std::shared_ptr<Formatter> Default();

    using Ptr = std::shared_ptr<Formatter>;
};

class FormatterField {
public:
    virtual ~FormatterField() = default;
    virtual void Format(const EventPtr& event, std::ostream& out) const = 0;
    virtual std::string Tag() const = 0;
};

}
#endif // WS_LOG_FORMATTER_H

#ifndef WS_LOG_APPENDER_H
#define WS_LOG_APPENDER_H

#include <memory>
#include <string>
#include <iostream>
#include <fstream>

namespace ws::log {

class Event;
class Formatter;
enum class AppenderType;

class Appender {
public:
    virtual ~Appender() = default;
    virtual void Log(const EventPtr& event) = 0;
    virtual std::string ToYamlString() const = 0;

    void SetFormatter(const Formatter::Ptr& formatter);

protected:
    Appender() = default;

    Formatter::Ptr formatter_; 

    using Ptr = std::shared_ptr<Appender>;
};

}
#endif // WS_LOG_APPENDER_H

#ifndef WS_LOG_STDOUT_APPENDER_H
#define WS_LOG_STDOUT_APPENDER_H

#include "ws/log/appender.h"
#include <iostream>

namespace ws::log {

class StdOutAppender : public Appender {
public:
    StdOutAppender();
    void Log(const EventPtr& event) override;
    std::string ToYamlString() const override;
};

}
#endif // WS_LOG_STDOUT_APPENDER_H

#ifndef WS_LOG_FILE_APPENDER_H
#define WS_LOG_FILE_APPENDER_H

#include "ws/log/appender.h"
#include <fstream>
#include <stdexcept>

namespace ws::log {

class FileAppender : public Appender {
public:
    FileAppender(const std::string& filename);
    void Log(const EventPtr& event) override;
    std::string ToYamlString() const override;
private:
    std::ofstream file_; 
};

}
#endif // WS_LOG_FILE_APPENDER_H
